// All explanations, examples and practice questions are authored for this app.
func ge(japanese, reading, meaning string) domain.GrammarExample {
	return domain.GrammarExample{Japanese: japanese, Reading: reading, Meaning: meaning}
}
func gp(pattern, meaning, formation, explanation, mistake string, examples ...domain.GrammarExample) domain.GrammarPoint {
	return domain.GrammarPoint{Pattern: pattern, Meaning: meaning, Formation: formation, Explanation: explanation, CommonMistake: mistake, Examples: examples}
}
func gq(prompt, explanation string, choices ...string) grammarQuestionContent {
	return grammarQuestionContent{Prompt: prompt, Explanation: explanation, Choices: choices, Correct: 0}
}
func gl(chapter, title string, points []domain.GrammarPoint, questions ...grammarQuestionContent) grammarLessonContent {
	return grammarLessonContent{Chapter: chapter, Title: title, Points: points, Questions: questions}
}

